@startuml

class Bank {}

class Branch {}

class Customer {
  + firstName : string
  + lastName : string
}

class Account {
  + accountNumber : int
  + balance : double
}

class SavingsAccount extends Account {}

class CheckingAccount extends Account {
  + overdraftLimit : double
}

Bank "1" -- "*" Customer
Bank "1" *-- "*" Branch
Customer "1" -- "1..5" Account
Account "1" -- "1" Customer : owner

@enduml

